<?php
$page_title='ออเดอร์ร้านค้า';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/commerce_workflow.php';$db=(new Database())->getConnection();$sellerId=(int)$_SESSION['user_id'];$message=$error='';$q=$db->prepare("SELECT store_status,order_processing_enabled FROM seller_profiles WHERE user_id=? AND status='approved'");$q->execute([$sellerId]);$control=$q->fetch();if(!$control){header('Location: '.BASE_URL.'seller.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{if($control['store_status']!=='active'||!(int)$control['order_processing_enabled'])throw new RuntimeException('ร้านถูกจำกัดการจัดการออเดอร์');$orderId=(int)($_POST['order_id']??0);$status=(string)($_POST['status']??'');$carrier=trim((string)($_POST['carrier']??''));$tracking=trim((string)($_POST['tracking_number']??''));if($status==='shipped'&&($carrier===''||$tracking===''))throw new RuntimeException('กรุณากรอกบริษัทขนส่งและเลขพัสดุ');$db->beginTransaction();$q=$db->prepare('SELECT 1 FROM order_items WHERE order_id=? AND seller_id=?');$q->execute([$orderId,$sellerId]);if(!$q->fetchColumn())throw new RuntimeException('ไม่มีสิทธิ์จัดการออเดอร์นี้');$q=$db->prepare("SELECT COALESCE(status,'pending') FROM order_fulfillments WHERE order_id=? AND seller_id=? FOR UPDATE");$q->execute([$orderId,$sellerId]);$old=(string)($q->fetchColumn()?:'pending');$allowed=['pending'=>'accepted','accepted'=>'packing','packing'=>'shipped','shipped'=>'delivered'];if(($allowed[$old]??'')!==$status)throw new RuntimeException('กรุณาอัปเดตตามลำดับทีละขั้น');$q=$db->prepare("INSERT INTO order_fulfillments(order_id,seller_id,status,carrier,tracking_number,shipped_at,delivered_at) VALUES(?,?,?,?,?,IF(?='shipped',NOW(),NULL),IF(?='delivered',NOW(),NULL)) ON DUPLICATE KEY UPDATE status=VALUES(status),carrier=VALUES(carrier),tracking_number=VALUES(tracking_number),shipped_at=COALESCE(shipped_at,VALUES(shipped_at)),delivered_at=COALESCE(delivered_at,VALUES(delivered_at))");$q->execute([$orderId,$sellerId,$status,$carrier?:null,$tracking?:null,$status,$status]);syncOrderFromFulfillments($db,$orderId,$sellerId);$q=$db->prepare('SELECT user_id,order_no,order_status FROM orders WHERE id=?');$q->execute([$orderId]);$o=$q->fetch();if($o['order_status']==='completed')ensureSellerLedgerForOrder($db,$orderId);$db->commit();createNotification($db,(int)$o['user_id'],'order','ร้านค้าอัปเดตการจัดส่ง','ออเดอร์ '.$o['order_no'].' เปลี่ยนเป็น '.$status,BASE_URL.'order-detail.php?id='.$orderId);$message='อัปเดตการจัดส่งแล้ว';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$filter=(string)($_GET['status']??'all');$params=[$sellerId,$sellerId];$where="oi.seller_id=? AND o.order_status<>'cancelled' AND (o.payment_method='cod' OR o.payment_status='paid')";if(in_array($filter,['pending','accepted','packing','shipped','delivered'],true)){$where.=" AND COALESCE(f.status,'pending')=?";$params[]=$filter;}$q=$db->prepare("SELECT o.id,o.order_no,o.shipping_name,o.shipping_phone,o.shipping_address,o.created_at,COALESCE(f.status,'pending') fulfillment_status,f.carrier,f.tracking_number,SUM(oi.subtotal) seller_total,GROUP_CONCAT(CONCAT(oi.product_name,' × ',oi.quantity) SEPARATOR ' | ') items FROM orders o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE $where GROUP BY o.id,f.id ORDER BY o.id DESC");$q->execute($params);$orders=$q->fetchAll();require_once __DIR__.'/includes/header.php';$labels=['pending'=>'รอรับออเดอร์','accepted'=>'รับแล้ว','packing'=>'กำลังแพ็ก','shipped'=>'จัดส่งแล้ว','delivered'=>'ส่งสำเร็จ'];?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/seller.css"><main id="main-content" class="seller-workspace"><div class="container"><?php require __DIR__.'/includes/seller_nav.php';?><a class="seller-back" href="seller-dashboard.php"><i class="fa-solid fa-arrow-left"></i> กลับหน้าภาพรวม</a><header class="seller-page-head"><div><p class="eyebrow">ORDER FULFILLMENT</p><h1>ออเดอร์และการจัดส่ง</h1><p>ทำตามลำดับ รับออเดอร์ → แพ็กสินค้า → ใส่เลขพัสดุ → ยืนยันส่งสำเร็จ</p></div></header><section class="seller-guide"><div><b>1</b><span><strong>รับออเดอร์</strong><small>ตรวจสินค้าและกดยืนยันรับภายใน 24 ชั่วโมง</small></span></div><div><b>2</b><span><strong>แพ็กและส่ง</strong><small>เมื่อส่งแล้วต้องกรอกบริษัทขนส่งกับเลขติดตาม</small></span></div><div><b>3</b><span><strong>ปิดงาน</strong><small>ยืนยันส่งสำเร็จเพื่อให้ระบบลงยอดในกระเป๋าร้าน</small></span></div></section><?php if($message):?><p class="seller-success"><?php echo e($message);?></p><?php endif;?><?php if($error):?><p class="seller-error"><?php echo e($error);?></p><?php endif;?><div class="seller-toolbar"><form method="get"><select name="status"><option value="all">ทุกสถานะ</option><?php foreach($labels as $k=>$v):?><option value="<?php echo $k;?>" <?php echo $filter===$k?'selected':'';?>><?php echo $v;?></option><?php endforeach;?></select><button class="btn btn-primary">กรองออเดอร์</button></form><span><?php echo count($orders);?> รายการ</span></div><?php if(!$orders):?><section class="seller-empty-state"><div><i class="fa-solid fa-box"></i><h2>ยังไม่มีออเดอร์ในสถานะนี้</h2><p>ออเดอร์ PromptPay จะแสดงหลังชำระสำเร็จ ส่วน COD จะแสดงทันทีหลังลูกค้ายืนยันคำสั่งซื้อ</p><a class="btn btn-outline" href="seller-orders.php">ดูทุกสถานะ</a></div></section><?php endif;?>
<div style="display:grid;gap:16px"><?php foreach($orders as $o):$next=['pending'=>'accepted','accepted'=>'packing','packing'=>'shipped','shipped'=>'delivered'][$o['fulfillment_status']]??'';?><article class="admin-panel seller-order-card"><header><div><h3><?php echo e($o['order_no']);?></h3><small><?php echo date('d/m/Y H:i',strtotime($o['created_at']));?> · <?php echo e($labels[$o['fulfillment_status']]??$o['fulfillment_status']);?></small></div><strong><?php echo formatCurrency($o['seller_total']);?></strong></header><div class="seller-order-body"><div class="seller-order-customer"><strong><?php echo e($o['shipping_name']);?> · <?php echo e($o['shipping_phone']);?></strong><p><?php echo e($o['shipping_address']);?></p><p class="seller-order-items"><?php echo e($o['items']);?></p></div><div><?php if($next):?><form method="post" class="admin-form-grid"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="order_id" value="<?php echo $o['id'];?>"><label>ขั้นตอนถัดไป<select name="status"><option value="<?php echo $next;?>"><?php echo e($labels[$next]);?></option></select></label><label>บริษัทขนส่ง<input name="carrier" value="<?php echo e($o['carrier']);?>" placeholder="เช่น Flash Express"></label><label>เลขติดตามพัสดุ<input name="tracking_number" value="<?php echo e($o['tracking_number']);?>" placeholder="กรอกเมื่อเลือกจัดส่งแล้ว"></label><button class="btn btn-primary">บันทึกขั้นตอนถัดไป</button></form><?php else:?><p class="seller-success"><i class="fa-solid fa-circle-check"></i> ออเดอร์นี้ส่งสำเร็จแล้ว</p><?php endif;?></div></div></article><?php endforeach;?></div></div></main><?php require_once __DIR__.'/includes/footer.php';?>
